//! The converter against scenes recorded from the real TypeScript implementation.
//!
//! `scenes.json` is generated by `rust/codegen/generate-osm-scenes.mjs`; every scene's
//! expected output is what `convertOSMToGeoJSON` returned, in order.

use osd_osm::overpass::convert_overpass_json;
use serde_json::{Value, json};

/// Structural equality that treats numbers as `f64`.
///
/// JavaScript's `JSON.stringify` writes `-0` as `0`, whereas serde_json keeps the sign, so
/// the two documents can differ in representation for a coordinate that is negative zero.
/// The values are the same; writers must remember to normalise it (see `osd-out`).
fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same(p, q))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter()
                    .all(|(key, p)| y.get(key).is_some_and(|q| same(p, q)))
        }
        _ => a == b,
    }
}

#[test]
fn every_recorded_scene_is_reproduced_exactly() {
    let scenes: Value = serde_json::from_str(include_str!("scenes.json")).unwrap();
    let scenes = scenes["scenes"].as_array().unwrap();
    assert!(scenes.len() >= 19, "scene file looks truncated");

    let mut failures = Vec::new();
    for scene in scenes {
        let name = scene["name"].as_str().unwrap();
        let document = json!({ "elements": scene["elements"] }).to_string();
        let actual: Vec<Value> = convert_overpass_json(document.as_bytes())
            .unwrap_or_else(|error| panic!("scene {name:?}: {error:#}"))
            .iter()
            .map(|feature| feature.to_geojson())
            .collect();
        let expected = scene["expected"].as_array().unwrap();

        if actual.len() != expected.len() {
            failures.push(format!(
                "{name}: {} features, expected {}\n  actual:   {:?}\n  expected: {:?}",
                actual.len(),
                expected.len(),
                actual.iter().map(|f| f["id"].clone()).collect::<Vec<_>>(),
                expected.iter().map(|f| f["id"].clone()).collect::<Vec<_>>(),
            ));
            continue;
        }
        for (index, (a, e)) in actual.iter().zip(expected).enumerate() {
            if !same(a, e) {
                failures.push(format!(
                    "{name}: feature {index} differs\n  actual:   {a}\n  expected: {e}"
                ));
            }
        }
    }
    assert!(failures.is_empty(), "\n{}", failures.join("\n"));
}
